export function recite(startVerse: number, endVerse: number): string {
  if (startVerse < 1 || endVerse > 12 || startVerse > endVerse) {
    throw new Error("Invalid verse range");
  }

  const gifts: string[] = [
    "",
    "a Partridge in a Pear Tree",
    "two Turtle Doves",
    "three French Hens",
    "four Calling Birds",
    "five Gold Rings",
    "six Geese-a-Laying",
    "seven Swans-a-Swimming",
    "eight Maids-a-Milking",
    "nine Ladies Dancing",
    "ten Lords-a-Leaping",
    "eleven Pipers Piping",
    "twelve Drummers Drumming",
  ];

  const verses: string[] = [];

  for (let i = startVerse; i <= endVerse; i++) {
    let verse = `On the ${i}th day of Christmas my true love gave to me: `;

    for (let j = i; j >= 1; j--) {
      if (j === 1 && i > 1) {
        verse += `and ${gifts[j]}`;
      } else {
        verse += gifts[j];
      }

      if (j > 1) {
        verse += ", ";
      }
    }

    verse += ".";
    verses.push(verse);
  }

  return verses.join("\n") + "\n";
}
